INSERT INTO "questions" VALUES(1,1,'수학','electric','12 + 3 = ?','["14","15","16","13","17"]',1,'일의 자리 2에 3을 더하면 5예요. 그래서 15예요.','2026-09-26T09:23:42.253Z');
