INSERT INTO "questions" VALUES(3,1,'수학','rock','31 + 6 = ?','["37","36","38","35","39"]',0,'일의 자리 1에 6을 더하면 7이에요. 그래서 37이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(4,1,'수학','electric','48 − 5 = ?','["43","45","53","42","44"]',0,'일의 자리 8에서 5를 빼면 3이에요. 그래서 43이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(5,1,'수학','steel','23 + 14 = ?','["37","47","36","27","38"]',0,'십의 자리 2와 1을 더하면 3, 일의 자리 3과 4를 더하면 7이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(6,1,'수학','rock','57 − 24 = ?','["33","43","31","34","23"]',0,'십의 자리 5에서 2를 빼면 3, 일의 자리 7에서 4를 빼면 3이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(7,1,'수학','electric','42 + 16 = ?','["68","56","58","48","57"]',2,'십의 자리 4와 1을 더하면 5, 일의 자리 2와 6을 더하면 8이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(8,1,'국어','normal','의자에 바르게 ___. 알맞은 낱말은?','["안아요","앚아요","앉아요","안자요","앉자요"]',2,'앉아요의 앉에는 겹받침 ㄵ이 있어요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(9,1,'국어','fairy','물건을 살 때 내는 돈의 크기를 뜻하는 낱말은?','["갑","값","갓","갚","갔"]',1,'값에는 겹받침 ㅄ이 있어요. 물건의 값을 치르고 사요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(10,1,'국어','psychic','알을 낳고 꼬꼬댁 우는 동물의 이름은?','["닥","닭","닦","달","닼"]',1,'닭에는 겹받침 ㄺ이 있어요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(11,1,'국어','normal','일곱 다음의 수를 한글로 바르게 쓴 것은?','["여덥","여덜","여덟","여덞","여덕"]',2,'여덟에는 겹받침 ㄼ이 있어요. 일곱 다음은 여덟이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(12,1,'국어','psychic','운동장이 아주 ___. 알맞은 낱말은?','["널어요","넓어요","넙어요","너러요","넒어요"]',1,'넓어요의 넓에는 겹받침 ㄼ이 있어요. 공간이 크다는 뜻이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(13,1,'국어','fairy','빈 상자라서 안에 아무것도 ___.','["업어요","엇어요","없어요","업서요","엎어요"]',2,'없어요의 없에는 겹받침 ㅄ이 있어요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(14,1,'국어','normal','책을 소리 내어 ___. 알맞은 낱말은?','["읽어요","일어요","익어요","잃어요","읶어요"]',0,'읽어요의 읽에는 겹받침 ㄺ이 있어요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(15,1,'영어','water','''apple''은 무엇일까요?','["사과","바나나","포도","딸기","수박"]',0,'apple은 사과예요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(16,1,'영어','ice','고양이를 영어로 하면?','["dog","cat","cow","pig","hen"]',1,'고양이는 cat이에요. dog는 강아지예요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(17,1,'영어','flying','''red''는 무슨 색일까요?','["파란색","노란색","빨간색","초록색","검은색"]',2,'red는 빨간색이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(18,1,'영어','water','숫자 3을 영어로 하면?','["one","two","three","four","five"]',2,'1은 one, 2는 two, 3은 three예요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(19,1,'영어','ice','아침에 만났을 때 하는 인사는?','["Good morning","Good night","Goodbye","Thank you","Sorry"]',0,'아침 인사는 Good morning이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(20,1,'영어','flying','알파벳 ''A'' 다음에 오는 글자는?','["C","B","D","E","Z"]',1,'A, B, C 순서예요. A 다음은 B예요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(21,1,'영어','water','''sun''은 무엇일까요?','["달","별","해","구름","비"]',2,'sun은 해예요. 달은 moon이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(22,1,'한자','fighting','山의 뜻과 소리는?','["물 수","산 산","사람 인","날 일","불 화"]',1,'山은 산 산이에요. 산을 뜻해요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(23,1,'한자','dragon','水의 뜻과 소리는?','["물 수","나무 목","달 월","산 산","흙 토"]',0,'水는 물 수예요. 물을 뜻해요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(24,1,'한자','fire','木의 뜻과 소리는?','["불 화","나무 목","산 산","쇠 금","물 수"]',1,'木은 나무 목이에요. 나무를 뜻해요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(25,1,'한자','fire','人의 뜻과 소리는?','["사람 인","날 일","달 월","큰 대","들 입"]',0,'人은 사람 인이에요. 사람을 뜻해요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(26,1,'한자','dragon','日의 뜻과 소리는?','["달 월","날 일","나무 목","눈 목","흰 백"]',1,'日은 날 일이에요. 날이나 해를 뜻해요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(27,1,'한자','fighting','月의 뜻과 소리는?','["물 수","사람 인","달 월","날 일","밭 전"]',2,'月은 달 월이에요. 하늘의 달을 뜻해요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(28,1,'한자','dragon','學의 뜻과 소리는?','["학교 교","배울 학","큰 대","글월 문","아들 자"]',1,'學은 배울 학이에요. 배우는 것을 뜻해요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(29,1,'상식','grass','식물은 주로 어느 부분으로 땅속의 물을 빨아들일까요?','["뿌리","꽃","열매","잎","씨앗"]',0,'뿌리는 식물을 지탱하고 땅속의 물을 빨아들여요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(30,1,'상식','ground','물고기는 주로 무엇으로 물속에서 숨을 쉴까요?','["날개","귀","아가미","꼬리","지느러미"]',2,'물고기는 아가미로 물속에 녹아 있는 산소를 얻어요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(31,1,'상식','bug','나비의 애벌레가 다음에 되는 모습은?','["새","물고기","번데기","올챙이","알"]',2,'나비는 알, 애벌레, 번데기를 거쳐 어른벌레가 돼요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(32,1,'상식','ground','낮에 지구에 빛과 열을 보내 주는 것은?','["돌","태양","모래","구름","달"]',1,'태양은 지구에 빛과 열을 보내 줘요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(33,1,'상식','ground','얼음을 따뜻한 곳에 두면 어떻게 될까요?','["돌이 돼요","더 단단해져요","녹아서 물이 돼요","더 커져요","색이 바뀌어요"]',2,'얼음은 따뜻해지면 녹아서 물이 돼요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(34,1,'상식','bug','곤충인 꿀벌의 다리는 모두 몇 개일까요?','["6개","2개","8개","4개","10개"]',0,'곤충의 다리는 세 쌍, 모두 6개예요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(35,1,'상식','grass','가을에 은행나무의 잎은 보통 무슨 색으로 변할까요?','["파란색","노란색","보라색","검은색","분홍색"]',1,'가을이 되면 은행나무 잎은 노랗게 물들어요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(36,1,'역사','ghost','구석기 사람들이 돌을 깨뜨려 만든 도구는?','["종이책","뗀석기","플라스틱 숟가락","유리컵","쇠 냄비"]',1,'뗀석기는 돌을 깨뜨리거나 떼어 만든 도구예요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(37,1,'역사','poison','구석기 사람들은 주로 어떻게 먹을 것을 구했을까요?','["마트에서 사기","배달시키기","사냥하고 열매 따기","식당에 가기","공장에서 만들기"]',2,'짐승을 사냥하고 열매를 모으며 먹을 것을 구했어요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(38,1,'역사','dark','신석기 사람들이 돌을 갈아 만든 도구는?','["간석기","고무 지우개","유리컵","플라스틱 자","종이컵"]',0,'간석기는 돌을 갈고 다듬어서 만든 도구예요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(39,1,'역사','ghost','신석기 사람들이 흙으로 빚어 구운 그릇은?','["비닐봉지","종이 상자","토기","유리병","캔"]',2,'토기는 흙으로 빚어서 구운 그릇이에요. 음식을 담거나 저장했어요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(40,1,'역사','dark','신석기 사람들은 땅을 파고 지붕을 덮은 집에 살았어요. 이 집은?','["아파트","움집","우주 정거장","빌딩","기와집"]',1,'움집은 땅을 파고 기둥과 지붕을 세워 만든 집이에요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(41,1,'역사','poison','구석기 사람들이 불을 이용해서 할 수 있었던 일은?','["휴대 전화 충전하기","추위를 이기고 음식 익히기","자동차 운전하기","텔레비전 보기","비행기 타기"]',1,'불로 몸을 따뜻하게 하고 음식을 익힐 수 있었어요.','2026-09-26T09:23:42.253Z');
INSERT INTO "questions" VALUES(42,1,'역사','ghost','구석기 시대 다음에 오는 시대는?','["우주 시대","신석기 시대","공룡 시대","로봇 시대","컴퓨터 시대"]',1,'구석기 시대 다음은 신석기 시대예요. 돌을 갈아 만든 도구를 사용했어요.','2026-09-26T09:23:42.253Z');
