INSERT INTO "questions" VALUES(670,3,'국어','normal','다음 중 받침을 바르게 쓴 음식 이름은?','["볶금밥","복끔밥","복음밥","볶움밥","볶음밥"]',4,'''볶다''에서 온 말이라 ''볶음밥''이라고 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(671,3,'국어','normal','신발 끈에 대해 쓴 문장 가운데 받침을 바르게 쓴 것은?','["나는 신발 끈을 묶엇어요.","나는 신발 끈을 묵었어요.","나는 신발 끈을 묵어써요.","나는 신발 끈을 묶었어요.","나는 신발 끈을 묶었서요."]',3,'''묶었어요''는 받침에 ㄲ과 ㅆ을 모두 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(672,3,'국어','normal','다음 중 받침이 ㄱ이 아니라 ㄲ인 낱말은?','["먹다","녹다","박다","섞다","막다"]',3,'''섞다''는 받침에 ㄲ을 써요.','2026-09-27T01:10:33.910Z');
