INSERT INTO "questions" VALUES(695,3,'국어','fairy','"나는 웃는 모습이 아빠를 많이 (   )았어요." 괄호에 알맞은 글자는?','["달","닮","닲","닯","담"]',1,'''닮다''는 겹받침 ㄻ을 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(696,3,'국어','fairy','"아침을 (   )으면 배가 많이 고파요." 괄호에 알맞은 글자는?','["굴","굷","굼","굵","굶"]',4,'''굶다''는 겹받침 ㄻ을 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(697,3,'국어','fairy','"강아지가 내 손을 혀로 (   )았어요." 괄호에 알맞은 글자는?','["햝","핥","할","핦","핧"]',1,'''핥다''는 겹받침 ㄾ을 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(698,3,'국어','fairy','"모기에 물린 곳을 (   )으면 안 돼요." 괄호에 알맞은 글자는?','["긇","극","긃","글","긁"]',4,'''긁다''는 겹받침 ㄺ을 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(699,3,'국어','fairy','"가을이 되자 단풍잎이 (   )게 물들었어요." 괄호에 알맞은 글자는?','["붉","붋","붊","불","북"]',0,'''붉다''는 겹받침 ㄺ을 써요.','2026-09-27T01:10:33.910Z');
