INSERT INTO "questions" VALUES(810,3,'수학','rock','피카츄는 딱지 6장, 나옹은 딱지 5장을 가지고 있어요. 두 포켓몬이 가진 딱지는 모두 몇 장일까요?','["21장","22장","1장","10장","11장"]',4,'6+5=11, 모두 11장','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(811,3,'수학','rock','모래두지는 구슬 9개, 푸린은 구슬 6개를 가지고 있어요. 두 포켓몬이 가진 구슬은 모두 몇 개일까요?','["16개","14개","5개","17개","15개"]',4,'9+6=15, 모두 15개','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(812,3,'수학','rock','이상해씨는 딱지 9장, 꼬부기는 딱지 7장을 가지고 있어요. 두 포켓몬이 가진 딱지는 모두 몇 장일까요?','["19장","16장","6장","14장","15장"]',1,'9+7=16, 모두 16장','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(813,3,'수학','rock','나무에 참새가 9마리 앉아 있었어요. 6마리가 더 날아왔어요. 나무에 앉은 참새는 모두 몇 마리일까요?','["3마리","13마리","16마리","25마리","15마리"]',4,'더 날아왔으니 더해요. 9+6=15','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(814,3,'수학','rock','나무에 비둘기가 6마리 앉아 있었어요. 6마리가 더 날아왔어요. 나무에 앉은 비둘기는 모두 몇 마리일까요?','["23마리","11마리","15마리","2마리","12마리"]',4,'더 날아왔으니 더해요. 6+6=12','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(815,3,'수학','rock','나무에 까치가 8마리 앉아 있었어요. 8마리가 더 날아왔어요. 나무에 앉은 까치는 모두 몇 마리일까요?','["6마리","17마리","16마리","18마리","19마리"]',2,'더 날아왔으니 더해요. 8+8=16','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(816,3,'수학','rock','고라파덕이 딸기 17개 가운데 9개를 먹었어요. 남은 딸기는 몇 개일까요?','["6개","8개","18개","19개","10개"]',1,'먹은 만큼 빼요. 17-9=8','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(817,3,'수학','rock','파이리가 귤 15개 가운데 9개를 먹었어요. 남은 귤은 몇 개일까요?','["16개","4개","6개","3개","17개"]',2,'먹은 만큼 빼요. 15-9=6','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(818,3,'수학','rock','피카츄가 딸기 18개 가운데 9개를 먹었어요. 남은 딸기는 몇 개일까요?','["6개","7개","9개","10개","12개"]',2,'먹은 만큼 빼요. 18-9=9','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(819,3,'수학','rock','푸린은 열매를 11개, 고라파덕은 6개 모았어요. 푸린은 고라파덕보다 몇 개 더 많이 모았을까요?','["4개","7개","5개","15개","17개"]',2,'더 많은 수에서 적은 수를 빼요. 11-6=5','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(820,3,'수학','rock','모래두지는 열매를 16개, 파이리는 3개 모았어요. 모래두지는 파이리보다 몇 개 더 많이 모았을까요?','["13개","23개","24개","19개","12개"]',0,'더 많은 수에서 적은 수를 빼요. 16-3=13','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(821,3,'수학','rock','모래두지는 열매를 12개, 이브이는 9개 모았어요. 모래두지는 이브이보다 몇 개 더 많이 모았을까요?','["3개","14개","4개","21개","0개"]',0,'더 많은 수에서 적은 수를 빼요. 12-9=3','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(822,3,'수학','rock','교실 책꽂이에 동화책이 33권, 그림책이 32권 있어요. 책은 모두 몇 권일까요?','["75권","64권","65권","63권","55권"]',2,'33+32=65','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(823,3,'수학','rock','교실 책꽂이에 동화책이 33권, 그림책이 16권 있어요. 책은 모두 몇 권일까요?','["49권","39권","59권","48권","51권"]',0,'33+16=49','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(824,3,'수학','rock','교실 책꽂이에 동화책이 22권, 그림책이 34권 있어요. 책은 모두 몇 권일까요?','["66권","58권","56권","46권","54권"]',2,'22+34=56','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(825,3,'수학','rock','색종이가 74장 있었어요. 종이접기를 하느라 3장을 썼어요. 남은 색종이는 몇 장일까요?','["77장","72장","70장","71장","74장"]',3,'쓴 만큼 빼요. 74-3=71','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(826,3,'수학','rock','색종이가 55장 있었어요. 종이접기를 하느라 2장을 썼어요. 남은 색종이는 몇 장일까요?','["57장","50장","63장","55장","53장"]',4,'쓴 만큼 빼요. 55-2=53','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(827,3,'수학','rock','색종이가 38장 있었어요. 종이접기를 하느라 1장을 썼어요. 남은 색종이는 몇 장일까요?','["36장","37장","27장","39장","38장"]',1,'쓴 만큼 빼요. 38-1=37','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(828,3,'수학','rock','이브이는 월요일에 열매를 6개, 화요일에 5개, 수요일에 3개 모았어요. 사흘 동안 모은 열매는 모두 몇 개일까요?','["11개","14개","16개","25개","17개"]',1,'6+5=11, 11+3=14','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(829,3,'수학','rock','모래두지는 월요일에 열매를 3개, 화요일에 4개, 수요일에 3개 모았어요. 사흘 동안 모은 열매는 모두 몇 개일까요?','["10개","20개","12개","13개","7개"]',0,'3+4=7, 7+3=10','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(830,3,'수학','rock','푸린은 월요일에 열매를 3개, 화요일에 2개, 수요일에 2개 모았어요. 사흘 동안 모은 열매는 모두 몇 개일까요?','["5개","7개","4개","6개","17개"]',1,'3+2=5, 5+2=7','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(831,3,'수학','rock','사탕 10개를 꼬부기와 나옹이 나누어 가졌어요. 꼬부기가 4개를 가졌다면 나옹은 몇 개를 가졌을까요?','["8개","9개","6개","16개","14개"]',2,'10을 4와 6으로 가를 수 있어요. 10-4=6','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(832,3,'수학','rock','사탕 10개를 피카츄와 푸린이 나누어 가졌어요. 피카츄가 5개를 가졌다면 푸린은 몇 개를 가졌을까요?','["15개","4개","2개","6개","5개"]',4,'10을 5와 5로 가를 수 있어요. 10-5=5','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(833,3,'수학','rock','사탕 10개를 잠만보와 고라파덕이 나누어 가졌어요. 잠만보가 7개를 가졌다면 고라파덕은 몇 개를 가졌을까요?','["3개","7개","4개","1개","14개"]',0,'10을 7과 3으로 가를 수 있어요. 10-7=3','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(834,3,'수학','rock','버스에 14명이 타고 있었어요. 이번 정류장에서 8명이 내렸어요. 버스에 남은 사람은 몇 명일까요?','["22명","8명","7명","6명","17명"]',3,'내린 만큼 빼요. 14-8=6','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(835,3,'수학','rock','버스에 14명이 타고 있었어요. 이번 정류장에서 9명이 내렸어요. 버스에 남은 사람은 몇 명일까요?','["15명","3명","2명","23명","5명"]',4,'내린 만큼 빼요. 14-9=5','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(836,3,'수학','rock','버스에 14명이 타고 있었어요. 이번 정류장에서 5명이 내렸어요. 버스에 남은 사람은 몇 명일까요?','["19명","9명","20명","7명","10명"]',1,'내린 만큼 빼요. 14-5=9','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(837,3,'수학','rock','줄넘기를 푸린은 89번, 이브이는 79번 넘었어요. 푸린은 이브이보다 몇 번 더 많이 넘었을까요?','["9번","13번","0번","10번","20번"]',3,'89-79=10','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(838,3,'수학','rock','줄넘기를 꼬부기는 48번, 잠만보는 21번 넘었어요. 꼬부기는 잠만보보다 몇 번 더 많이 넘었을까요?','["27번","17번","30번","37번","69번"]',0,'48-21=27','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(839,3,'수학','rock','줄넘기를 나옹은 86번, 모래두지는 45번 넘었어요. 나옹은 모래두지보다 몇 번 더 많이 넘었을까요?','["39번","41번","51번","38번","40번"]',1,'86-45=41','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(840,3,'수학','rock','구슬을 10개씩 6봉지와 10개씩 2봉지 샀어요. 구슬은 모두 몇 개일까요?','["91개","80개","8개","77개","79개"]',1,'10개씩 8봉지이므로 80개','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(841,3,'수학','rock','구슬을 10개씩 2봉지와 10개씩 2봉지 샀어요. 구슬은 모두 몇 개일까요?','["39개","40개","4개","37개","51개"]',1,'10개씩 4봉지이므로 40개','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(842,3,'수학','rock','구슬을 10개씩 4봉지와 10개씩 3봉지 샀어요. 구슬은 모두 몇 개일까요?','["72개","7개","81개","69개","70개"]',4,'10개씩 7봉지이므로 70개','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(843,3,'영어','water','''The dog is small.''에서 ''small''의 뜻은?','["즐거운","크다","커피","코트","작다"]',4,'small = 작다. 문장 뜻: 그 개는 작아요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(844,3,'영어','ice','빈칸에 알맞은 말은? The cup ___ empty. (그 컵은 비어 있어요.)','["like","am","have","are","is"]',4,'The cup(하나)에는 is를 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(845,3,'영어','flying','''The apple is red.''의 뜻으로 알맞은 것은?','["그 개는 커요.","그 사과는 빨간색이에요.","그 컵은 가득 차 있어요.","그 사과는 초록색이에요.","그 방은 깨끗해요."]',1,'red = 빨간색','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(846,3,'영어','water','''The room is clean.''에서 ''clean''의 뜻은?','["자동차","깨끗한","더러운","책상","닭고기"]',1,'clean = 깨끗한. 문장 뜻: 그 방은 깨끗해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(847,3,'영어','ice','빈칸에 알맞은 말은? The flowers ___ pink. (그 꽃들은 분홍색이에요.)','["is","likes","am","has","are"]',4,'The flowers(여럿)에는 are를 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(848,3,'영어','flying','''그 고양이들은 조용해요.''를 영어로 바르게 쓴 것은?','["The toys are fun.","The cats are quiet.","The cats are noisy.","The cats is quiet.","The flowers are pink."]',1,'The cats(여럿)에는 are를 써요. quiet = 조용한','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(849,3,'영어','water','''The toys are boring.''에서 ''boring''의 뜻은?','["지루한","주스","재미있는","탄산음료","블록들"]',0,'boring = 지루한. 문장 뜻: 그 장난감들은 지루해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(850,3,'영어','ice','빈칸에 알맞은 말은? The birds ___ fast. (그 새들은 빨라요.)','["are","has","likes","am","is"]',0,'The birds(여럿)에는 are를 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(851,3,'영어','flying','''I have a small bag.''의 뜻으로 알맞은 것은?','["나는 큰 가방이 있어요.","그들에게는 깨끗한 책상이 있어요.","나는 작은 가방이 있어요.","아이들은 즐거운 하루하루를 보내요.","우리는 새 크레파스가 있어요."]',2,'small = 작은','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(852,3,'영어','water','''We have old crayons.''에서 ''old''의 뜻은?','["가게","낡은","조용한","새로운","고양이들"]',1,'old = 낡은. 문장 뜻: 우리는 낡은 크레파스가 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(853,3,'영어','ice','빈칸에 알맞은 말은? They ___ dirty desks. (그들에게는 더러운 책상이 있어요.)','["has","am","likes","have","is"]',3,'They 뒤에는 have를 그대로 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(854,3,'영어','flying','''아이들은 즐거운 하루하루를 보내요.''를 영어로 바르게 쓴 것은?','["We have new crayons.","I have a big bag.","The kids have fun days.","The kids have busy days.","The kids has fun days."]',2,'The kids 뒤에는 have를 그대로 써요. fun = 즐거운','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(855,3,'영어','water','''The turtle has a hard shell.''에서 ''hard''의 뜻은?','["짧은","시끄러운","딱딱한","말랑한","선반"]',2,'hard = 딱딱한. 문장 뜻: 그 거북은 등딱지가 딱딱해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(856,3,'영어','ice','빈칸에 알맞은 말은? The girl ___ long hair. (그 여자아이는 머리카락이 길어요.)','["has","am","like","are","have"]',0,'The girl처럼 한 사람·한 개일 때는 has를 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(857,3,'영어','flying','''The robot has big eyes.''의 뜻으로 알맞은 것은?','["그 여자아이는 머리카락이 길어요.","그 로봇은 눈이 작아요.","그 사자는 꼬리가 커요.","그 로봇은 눈이 커요.","그 거북은 등딱지가 딱딱해요."]',3,'big = 큰','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(858,3,'영어','water','''The lion has a big tail.''에서 ''big''의 뜻은?','["키가 작은","커피","고양이들","큰","짧은"]',3,'big = 큰. 문장 뜻: 그 사자는 꼬리가 커요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(859,3,'영어','ice','빈칸에 알맞은 말은? The frog ___ jump. (개구리는 뛰어오를 수 있어요.)','["am","is","has","are","can"]',4,'can 뒤에는 움직임 낱말을 그대로 써요. → can','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(860,3,'영어','flying','''새는 깡충깡충 뛸 수 있어요.''를 영어로 바르게 쓴 것은?','["The frog can jump.","The bird can hop.","The bird is hop.","I can run.","The bird can fly."]',1,'can 뒤에는 움직임 낱말을 그대로 써요. → can hop = 깡충 뛰다','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(861,3,'영어','water','''I can run.''에서 ''run''의 뜻은?','["걷다","달리다","반려묘","공작품","신"]',1,'run = 달리다. 문장 뜻: 나는 달릴 수 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(862,3,'영어','ice','빈칸에 알맞은 말은? The robot ___ move. (로봇은 움직일 수 있어요.)','["can","is","am","are","has"]',0,'can 뒤에는 움직임 낱말을 그대로 써요. → can','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(863,3,'영어','flying','''I like juice.''의 뜻으로 알맞은 것은?','["나는 주스를 좋아해요.","그녀는 고양이를 좋아해요.","나는 우유를 좋아해요.","우리는 공원을 좋아해요.","그들은 해를 좋아해요."]',0,'juice = 주스','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(864,3,'영어','water','''She likes cats.''에서 ''cats''의 뜻은?','["부츠","가득 찬","고양이들","개들","키가 큰"]',2,'cats = 고양이들. 문장 뜻: 그녀는 고양이를 좋아해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(865,3,'영어','ice','빈칸에 알맞은 말은? They ___ the sun. (그들은 해를 좋아해요.)','["like","am","has","likes","is"]',0,'They 뒤에는 like를 그대로 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(866,3,'영어','flying','''우리는 공원을 좋아해요.''를 영어로 바르게 쓴 것은?','["She likes cats.","I like milk.","We like the park.","We likes the park.","We like the beach."]',2,'We 뒤에는 like를 그대로 써요. park = 공원','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(867,3,'영어','water','''I see a big turtle.''에서 ''big''의 뜻은?','["작은","큰","상자","바쁜","새로운"]',1,'big = 큰. 문장 뜻: 나는 큰 거북을 봐요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(868,3,'영어','ice','빈칸에 알맞은 말은? I ___ a yellow flower. (나는 노란색 꽃을 봐요.)','["see","sees","is","are","has"]',0,'I 뒤에는 see를 그대로 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(869,3,'영어','flying','''I see a red bird.''의 뜻으로 알맞은 것은?','["나는 빨간 새를 봐요.","나는 파란 새를 봐요.","나는 긴 뱀을 봐요.","나는 큰 거북을 봐요.","나는 분홍색 꽃을 봐요."]',0,'red = 빨간색','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(870,3,'영어','water','''I see a short snake.''에서 ''short''의 뜻은?','["미끄럼틀","짧은","반려견","긴","시리얼"]',1,'short = 짧은. 문장 뜻: 나는 짧은 뱀을 봐요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(871,3,'영어','ice','빈칸에 알맞은 말은? The cloud ___ fluffy. (구름이 폭신폭신해 보여요.)','["am","are","look","like","looks"]',4,'The cloud처럼 한 사람·한 개일 때는 look에 s를 붙인 looks를 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(872,3,'영어','flying','''그 개는 행복해 보여요.''를 영어로 바르게 쓴 것은?','["The dog looks happy.","The dog look happy.","The dog looks sad.","The tree looks tall.","The cloud looks big."]',0,'The dog처럼 한 사람·한 개일 때는 look에 s를 붙인 looks를 써요. happy = 행복한','2026-09-27T01:10:33.910Z');
