INSERT INTO "questions" VALUES(928,3,'영어','ice','빈칸에 알맞은 말은? She ___ a marker. (그녀는 마커가 필요해요.)','["like","are","am","needs","need"]',3,'She처럼 한 사람·한 개일 때는 need에 s를 붙인 needs를 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(929,3,'영어','flying','''They need glue.''의 뜻으로 알맞은 것은?','["나는 연필이 필요해요.","그들은 종이가 필요해요.","그들은 풀이 필요해요.","그는 자가 필요해요.","그녀는 마커가 필요해요."]',2,'glue = 풀','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(930,3,'영어','water','''He needs a notebook.''에서 ''notebook''의 뜻은?','["밥","돌멩이","블록들","공책","자"]',3,'notebook = 공책. 문장 뜻: 그는 공책이 필요해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(931,3,'영어','ice','빈칸에 알맞은 말은? I ___ a rock. (나는 돌을 찾아요.)','["are","has","is","finds","find"]',4,'I 뒤에는 find를 그대로 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(932,3,'영어','flying','''그녀는 조개껍데기를 찾아요.''를 영어로 바르게 쓴 것은?','["They find a bug.","She finds a stone.","She find a shell.","I find a rock.","She finds a shell."]',4,'She처럼 한 사람·한 개일 때는 find에 s를 붙인 finds를 써요. shell = 조개껍데기','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(933,3,'영어','water','''They find a worm.''에서 ''worm''의 뜻은?','["벌레","간식","지렁이","과일","서류철"]',2,'worm = 지렁이. 문장 뜻: 그들은 지렁이를 찾아요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(934,3,'영어','ice','빈칸에 알맞은 말은? He ___ a coin. (그는 동전을 찾아요.)','["like","are","find","finds","am"]',3,'He처럼 한 사람·한 개일 때는 find에 s를 붙인 finds를 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(935,3,'영어','flying','''I open the door.''의 뜻으로 알맞은 것은?','["그는 병을 열어요.","그들은 책을 펼쳐요.","나는 창문을 열어요.","나는 문을 열어요.","그녀는 상자를 열어요."]',3,'door = 문','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(936,3,'영어','water','''She opens the box.''에서 ''box''의 뜻은?','["노래하는","바람","가방","상자","소파"]',3,'box = 상자. 문장 뜻: 그녀는 상자를 열어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(937,3,'영어','ice','빈칸에 알맞은 말은? They ___ the folder. (그들은 서류철을 펼쳐요.)','["opens","open","has","is","am"]',1,'They 뒤에는 open를 그대로 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(938,3,'영어','flying','''그는 병을 열어요.''를 영어로 바르게 쓴 것은?','["She opens the box.","He open the jar.","He opens the jar.","He opens the can.","I open the door."]',2,'He처럼 한 사람·한 개일 때는 open에 s를 붙인 opens를 써요. jar = 병','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(939,3,'영어','water','''I close the window.''에서 ''window''의 뜻은?','["과일","좋은","문","창문","침대"]',3,'window = 창문. 문장 뜻: 나는 창문을 닫아요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(940,3,'영어','ice','빈칸에 알맞은 말은? She ___ the box. (그녀는 상자를 닫아요.)','["like","close","am","are","closes"]',4,'She처럼 한 사람·한 개일 때는 close에 s를 붙인 closes를 써요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(941,3,'영어','flying','''They close the lunchbox.''의 뜻으로 알맞은 것은?','["그는 케이스를 닫아요.","나는 문을 닫아요.","그들은 서류철을 덮어요.","그들은 도시락통을 닫아요.","그녀는 상자를 닫아요."]',3,'lunchbox = 도시락통','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(942,3,'영어','water','''He closes the case.''에서 ''case''의 뜻은?','["시리얼","공책","새로운","말랑한","케이스"]',4,'case = 케이스. 문장 뜻: 그는 케이스를 닫아요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(943,3,'한자','dragon','"오늘은 【三月】 1일이에요." 【 】 안 한자어의 읽는 소리는?','["삼월","산월","삼일","석월","사월"]',0,'三(석 삼) + 月(달 월) = 삼월','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(944,3,'한자','dragon','"【六月】에는 비가 많이 와요." 【 】 안 한자어의 읽는 소리는?','["육월","오월","칠월","유월","륙월"]',3,'六月은 소리 내기 쉽게 ''유월''이라고 읽어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(945,3,'한자','dragon','"【十月】 9일은 한글날이에요." 【 】 안 한자어의 읽는 소리는?','["십월","십일","일월","열월","시월"]',4,'十月은 소리 내기 쉽게 ''시월''이라고 읽어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(946,3,'한자','dragon','"【父母】님께 감사 편지를 썼어요." 【 】 안 한자어의 읽는 소리는?','["모부","부녀","모녀","형제","부모"]',4,'父(아비 부) + 母(어미 모) = 부모','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(947,3,'한자','dragon','"우리 【兄弟】는 사이가 좋아요." 【 】 안 한자어의 읽는 소리는?','["형부","부모","자매","형제","제형"]',3,'兄(형 형) + 弟(아우 제) = 형제','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(948,3,'한자','dragon','"아침 일찍 【學校】에 가요." 【 】 안 한자어의 읽는 소리는?','["교실","학생","대학","학교","교학"]',3,'學(배울 학) + 校(학교 교) = 학교','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(949,3,'한자','dragon','"친구들과 【敎室】을 청소했어요." 【 】 안 한자어의 읽는 소리는?','["실내","교실","학교","교문","왕실"]',1,'敎(가르칠 교) + 室(집 실) = 교실','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(950,3,'한자','dragon','"【學生】들이 줄을 서요." 【 】 안 한자어의 읽는 소리는?','["학교","학생","생일","대학","선생"]',1,'學(배울 학) + 生(날 생) = 학생','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(951,3,'한자','dragon','"담임 【先生】님은 친절해요." 【 】 안 한자어의 읽는 소리는?','["선왕","생일","생선","선생","학생"]',3,'先(먼저 선) + 生(날 생) = 선생','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(952,3,'한자','dragon','"오늘은 내 【生日】이에요." 【 】 안 한자어의 읽는 소리는?','["생일","월일","일생","학생","생월"]',0,'生(날 생) + 日(날 일) = 생일','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(953,3,'한자','dragon','"【火山】에서 뜨거운 용암이 나와요." 【 】 안 한자어의 읽는 소리는?','["화목","산화","금산","화산","수산"]',3,'火(불 화) + 山(메 산) = 화산','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(954,3,'한자','dragon','"할머니 댁 【大門】이 활짝 열렸어요." 【 】 안 한자어의 읽는 소리는?','["대학","대문","교문","소문","남문"]',1,'大(큰 대) + 門(문 문) = 대문','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(955,3,'한자','dragon','"동화책 속 【女王】이 나타났어요." 【 】 안 한자어의 읽는 소리는?','["여왕","여자","왕녀","국왕","녀왕"]',0,'女(계집 녀) + 王(임금 왕), 낱말 맨 앞에서는 ''여''로 읽어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(956,3,'한자','dragon','"옛날 옛적에 【國王】이 살았어요." 【 】 안 한자어의 읽는 소리는?','["한국","국왕","국민","왕국","여왕"]',1,'國(나라 국) + 王(임금 왕) = 국왕','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(957,3,'한자','dragon','"【大韓民國】은 우리나라의 이름이에요." 【 】 안 한자어의 읽는 소리는?','["대민한국","대한제국","대한민국","한민대국","대한국민"]',2,'大(큰 대) + 韓(한국 한) + 民(백성 민) + 國(나라 국) = 대한민국','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(958,3,'한자','dragon','"【外國】에서 온 친구와 인사했어요." 【 】 안 한자어의 읽는 소리는?','["중국","외출","국외","외국","한국"]',3,'外(바깥 외) + 國(나라 국) = 외국','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(959,3,'한자','dragon','"모든 【國民】이 태극기를 달았어요." 【 】 안 한자어의 읽는 소리는?','["민국","한국","시민","국군","국민"]',4,'國(나라 국) + 民(백성 민) = 국민','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(960,3,'한자','dragon','"【三寸】이 선물을 사 주셨어요." 【 】 안 한자어의 읽는 소리는?','["삼월","삼촌","오촌","사촌","삼십"]',1,'三(석 삼) + 寸(마디 촌) = 삼촌','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(961,3,'한자','dragon','"가족과 【南山】에 올라갔어요." 【 】 안 한자어의 읽는 소리는?','["북산","남산","남문","서산","동산"]',1,'南(남녘 남) + 山(메 산) = 남산','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(962,3,'한자','dragon','"우리 누나는 【中學生】이에요." 【 】 안 한자어의 읽는 소리는?','["중학생","중국인","대학생","고등학생","초등학생"]',0,'中(가운데 중) + 學(배울 학) + 生(날 생)','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(963,3,'한자','dragon','"형은 【大學】에 다녀요." 【 】 안 한자어의 읽는 소리는?','["소학","학생","대문","학교","대학"]',4,'大(큰 대) + 學(배울 학) = 대학','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(964,3,'한자','dragon','"씩씩한 【靑年】이 도와주었어요." 【 】 안 한자어의 읽는 소리는?','["백년","청년","청소","소년","중년"]',1,'靑(푸를 청) + 年(해 년) = 청년','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(965,3,'한자','dragon','"거북은 【萬年】을 산다는 이야기가 있어요." 【 】 안 한자어의 읽는 소리는?','["만년","백년","십년","천년","일년"]',0,'萬(일만 만) + 年(해 년) = 만년','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(966,3,'한자','dragon','"학교 【東門】으로 들어가요." 【 】 안 한자어의 읽는 소리는?','["서문","동문","대문","남문","북문"]',1,'東(동녘 동) + 門(문 문) = 동문','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(967,3,'한자','dragon','"해가 【西山】으로 넘어가요." 【 】 안 한자어의 읽는 소리는?','["서산","서문","남산","동산","화산"]',0,'西(서녘 서) + 山(메 산) = 서산','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(968,3,'한자','dragon','"【北韓】은 우리나라의 북쪽에 있어요." 【 】 안 한자어의 읽는 소리는?','["동북","남한","북한","한국","북문"]',2,'北(북녘 북) + 韓(한국 한) = 북한','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(969,3,'한자','dragon','"10월 1일은 【國軍】의 날이에요." 【 】 안 한자어의 읽는 소리는?','["군국","한국","군인","국군","국민"]',3,'國(나라 국) + 軍(군사 군) = 국군','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(970,3,'한자','dragon','"비가 많이 와서 【水門】을 열었어요." 【 】 안 한자어의 읽는 소리는?','["수문","수산","대문","목문","화문"]',0,'水(물 수) + 門(문 문) = 수문','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(971,3,'한자','dragon','"할아버지께서 【山水】 그림을 그리셨어요." 【 】 안 한자어의 읽는 소리는?','["수산","화수","산화","산수","강산"]',3,'山(메 산) + 水(물 수) = 산수','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(972,3,'한자','dragon','"【一年】 동안 키가 많이 자랐어요." 【 】 안 한자어의 읽는 소리는?','["일년","만년","십년","일월","이년"]',0,'一(한 일) + 年(해 년) = 일년','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(973,3,'한자','dragon','"【王室】 가족이 궁궐에 살았어요." 【 】 안 한자어의 읽는 소리는?','["실내","국왕","교실","왕실","왕국"]',3,'王(임금 왕) + 室(집 실) = 왕실','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(974,3,'한자','dragon','"우리 집 【長女】는 우리 누나예요." 【 】 안 한자어의 읽는 소리는?','["장녀","장년","모녀","여왕","장남"]',0,'長(긴 장) + 女(계집 녀) = 장녀(맏딸)','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(975,3,'한자','dragon','"【五月】 5일은 어린이날이에요." 【 】 안 한자어의 읽는 소리는?','["오월","유월","사월","구월","오일"]',0,'五(다섯 오) + 月(달 월) = 오월','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(976,3,'한자','fire','다음 한자의 훈(뜻)과 음(소리)은? 【金】','["사람 인","메 산","먼저 선","불 화","쇠 금"]',4,'金 : 쇠 금','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(977,3,'한자','fire','다음 한자의 훈(뜻)과 음(소리)은? 【兄】','["날 생","형 형","푸를 청","먼저 선","두 이"]',1,'兄 : 형 형','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(978,3,'한자','fire','다음 한자의 훈(뜻)과 음(소리)은? 【年】','["해 년","일만 만","마디 촌","아우 제","군사 군"]',0,'年 : 해 년','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(979,3,'한자','fire','다음 한자의 훈(뜻)과 음(소리)은? 【長】','["해 년","백성 민","마디 촌","긴 장","일만 만"]',3,'長 : 긴 장','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(980,3,'한자','fire','다음 한자의 훈(뜻)과 음(소리)은? 【水】','["작을 소","물 수","집 실","불 화","날 일"]',1,'水 : 물 수','2026-09-27T01:10:33.910Z');
