INSERT INTO "questions" VALUES(1043,3,'역사','ghost','''선사 시대''는 어떤 때를 말할까요?','["앞으로 올 미래","바다 위에서 살던 때","글자로 기록을 남기기 전의 아주 먼 옛날","임금이 없던 조선 시대","전쟁이 많았던 때"]',2,'선사 시대는 역사(기록) 이전의 시대라는 뜻이에요.','2026-09-27T01:10:33.910Z');
