INSERT INTO "questions" VALUES(1047,3,'역사','ghost','시대의 차례를 바르게 늘어놓은 것은?','["신석기 → 구석기 → 청동기","구석기 → 청동기 → 신석기","청동기 → 신석기 → 구석기","신석기 → 청동기 → 구석기","구석기 → 신석기 → 청동기"]',4,'구석기, 신석기, 청동기 순서예요.','2026-09-27T01:10:33.910Z');
