INSERT INTO "questions" VALUES(1049,3,'역사','ghost','구석기 시대 사람들이 이곳저곳 옮겨 다니며 산 까닭은?','["여행을 좋아해서","학교에 가야 해서","왕이 시켜서","먹을 것을 찾아다녀야 해서","집이 너무 커서"]',3,'먹을 것이 떨어지면 다른 곳으로 옮겨 갔어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1050,3,'역사','ghost','구석기 시대 사람들이 살던 곳으로 알맞은 것은?','["동굴이나 막집","기와집","초가집","궁궐","아파트"]',0,'구석기 사람들은 동굴이나 간단한 막집에서 살았어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1051,3,'역사','ghost','선사 시대 사람들이 불을 피운 방법으로 알맞은 것은?','["가스레인지를 켜서","나무와 나무를 비벼서","성냥을 그어서","전기를 꽂아서","라이터를 켜서"]',1,'나무를 비비거나 돌을 부딪쳐 불을 피웠어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1052,3,'역사','ghost','신석기 시대에 사람들이 처음으로 시작한 일은?','["열매 따기","사냥하기","동굴에서 살기","농사짓기","불 사용하기"]',3,'농사는 신석기 시대에 시작되었어요. 나머지는 구석기 때부터 했어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1053,3,'역사','ghost','신석기 시대 사람들이 땅을 파고 기둥을 세워 지은 집은?','["동굴","아파트","궁궐","기와집","움집"]',4,'신석기 사람들은 움집을 짓고 살았어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1054,3,'역사','ghost','움집 한가운데에는 무엇이 있었을까요?','["수영장","불을 피우는 화덕","텔레비전","침대","냉장고"]',1,'화덕에서 음식을 익히고 몸을 녹였어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1055,3,'역사','ghost','신석기 사람들이 강가나 바닷가에 모여 산 까닭은?','["산에 오르기 싫어서","바닷물을 마시려고","물고기와 조개를 구하기 쉬워서","배를 타고 여행하려고","모래 놀이를 하려고"]',2,'물가에서 물고기와 조개를 잡기 쉬웠어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1056,3,'역사','ghost','신석기 사람들이 길들여 기르기 시작한 동물로 알맞은 것은?','["고래","코끼리","호랑이","개","사자"]',3,'신석기 사람들은 개와 돼지 같은 동물을 기르기 시작했어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1057,3,'역사','ghost','신석기 사람들이 농사지은 곡식으로 알맞은 것은?','["초콜릿과 사탕","바나나와 파인애플","옥수수와 감자","사과와 포도","조와 수수"]',4,'신석기 사람들은 조, 피, 수수 같은 곡식을 길렀어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1058,3,'역사','ghost','신석기 시대 마을의 모습으로 알맞은 것은?','["자동차가 다녀요","큰 궁궐이 있어요","움집 여러 채가 모여 있어요","학교가 있어요","높은 빌딩이 많아요"]',2,'여러 가족이 움집을 짓고 모여 살았어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1059,3,'역사','ghost','청동기 시대에 생긴 변화로 알맞은 것은?','["글자로 일기를 썼어요","다스리는 사람과 따르는 사람이 생겼어요","농사를 그만두었어요","불을 처음 사용했어요","모두 동굴에서 살았어요"]',1,'청동기 시대에는 지배자(다스리는 사람)가 나타났어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1060,3,'역사','ghost','청동기 시대에 본격적으로 짓기 시작한 농사는?','["벼농사","사과 농사","커피 농사","바나나 농사","포도 농사"]',0,'청동기 시대에는 벼농사가 시작되었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1061,3,'역사','ghost','청동으로 만든 물건은 주로 누가 가졌을까요?','["지나가는 여행자","마을의 개","어린아이","모든 농부","힘 있는 지배자"]',4,'청동은 귀해서 지배자가 주로 가졌어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1062,3,'역사','ghost','청동기 시대 사람들이 마을 둘레에 울타리와 도랑을 만든 까닭은?','["비를 모으려고","꽃을 심으려고","물고기를 기르려고","다른 마을의 공격을 막으려고","놀이를 하려고"]',3,'마을끼리 다툼이 생겨 마을을 지키려고 했어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1063,3,'역사','ghost','떠돌아다니던 사람들이 한곳에 머물러 살게 된 까닭은?','["농사를 짓게 되어서","비가 와서","왕이 명령해서","동굴이 좋아서","사냥이 싫어서"]',0,'곡식을 기르고 거두려면 한곳에 머물러야 했어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1064,3,'역사','ghost','불을 사용하면서 달라진 점으로 알맞은 것은?','["책을 읽었어요","전화를 걸었어요","텔레비전을 봤어요","고기를 익혀 먹었어요","자동차를 탔어요"]',3,'불로 음식을 익혀 먹을 수 있었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1065,3,'역사','ghost','구석기 사람들이 사냥한 동물로 알맞은 것은?','["공룡","사슴","펭귄","캥거루","판다"]',1,'구석기 사람들은 사슴, 멧돼지 같은 동물을 사냥했어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1066,3,'역사','ghost','선사 시대 사람들은 공룡과 함께 살았을까요?','["공룡을 타고 다녔어요","아니요, 공룡은 훨씬 더 옛날에 사라졌어요","공룡을 집에서 길렀어요","공룡과 함께 농사를 지었어요","네, 함께 살았어요"]',1,'공룡은 사람이 나타나기 훨씬 전에 사라졌어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1067,3,'역사','ghost','''석기''의 ''석''은 무슨 뜻일까요?','["돌","쇠","불","나무","물"]',0,'석기는 돌로 만든 도구예요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1068,3,'역사','ghost','''청동''은 무엇일까요?','["구리와 주석을 섞어 만든 쇠붙이","단단한 돌","푸른 나무","투명한 유리","구운 흙"]',0,'청동은 구리에 주석을 섞은 금속이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1069,3,'역사','ghost','구석기, 신석기, 청동기 가운데 가장 오래된 시대는?','["알 수 없어요","신석기 시대","구석기 시대","셋 다 같아요","청동기 시대"]',2,'구석기 시대가 가장 오래되었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1070,3,'역사','ghost','고조선이 세워진 때는 어느 시대일까요?','["삼국 시대","청동기 시대","구석기 시대","조선 시대","신석기 시대"]',1,'고조선은 청동기 시대에 세워졌어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1071,3,'역사','ghost','신석기 사람들이 물고기를 잡을 때 쓴 것으로 알맞은 것은?','["그물과 작살","전기 낚싯대","잠수함","드론","총"]',0,'그물과 작살, 뼈로 만든 낚싯바늘을 썼어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1072,3,'역사','ghost','구석기 사람들이 무리를 지어 함께 다닌 까닭은?','["함께 사냥해야 큰 동물을 잡을 수 있어서","장사를 하려고","노래 대회를 하려고","학교에 가려고","왕을 뽑으려고"]',0,'여럿이 힘을 모아야 큰 동물을 사냥할 수 있었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1073,3,'역사','ghost','농사로 곡식이 남게 되자 생긴 일로 알맞은 것은?','["모두 동굴로 돌아갔어요","모두 똑같이 가난해졌어요","농사를 그만두었어요","많이 가진 사람과 적게 가진 사람이 생겼어요","곡식을 모두 버렸어요"]',3,'남는 곡식 때문에 가진 것의 차이가 생겼어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1074,3,'역사','ghost','글자가 없던 선사 시대의 모습을 우리는 어떻게 알 수 있을까요?','["옛날 일기장으로","땅속에서 나온 유물과 유적으로","옛날 신문으로","옛날 사진으로","녹음 파일로"]',1,'남아 있는 유물과 유적을 살펴서 알아내요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1075,3,'역사','ghost','옛날 사람들이 남긴 도구나 그릇 같은 물건을 무엇이라고 할까요?','["보석","쓰레기","화석","유물","장난감"]',3,'옛사람이 남긴 물건을 유물이라고 해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1076,3,'역사','ghost','옛날 사람들이 살았던 집터나 무덤처럼 흔적이 남아 있는 곳을 무엇이라고 할까요?','["유물","시장","유적","놀이터","공장"]',2,'옛사람의 흔적이 남은 곳을 유적이라고 해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1077,3,'역사','dark','우리나라 역사에서 가장 처음 세워진 나라는?','["고려","신라","백제","고조선","고구려"]',3,'우리 역사 최초의 나라는 고조선이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1078,3,'역사','dark','고조선을 세운 사람은?','["단군왕검","온조","주몽","환인","박혁거세"]',0,'단군왕검이 고조선을 세웠어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1079,3,'역사','dark','단군 이야기에서 환웅은 누구의 아들일까요?','["주몽","단군왕검","환인","풍백","웅녀"]',2,'환웅은 하늘나라 임금 환인의 아들이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1080,3,'역사','dark','환웅이 하늘에서 내려올 때 함께 데려온 세 신하는?','["주몽, 온조, 혁거세","청룡, 백호, 현무","풍백, 우사, 운사","곰, 호랑이, 토끼","해, 달, 별"]',2,'바람, 비, 구름을 다스리는 풍백, 우사, 운사예요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1081,3,'역사','dark','풍백, 우사, 운사가 다스린 것은?','["산, 강, 바다","바람, 비, 구름","불, 물, 흙","해, 달, 별","곰, 호랑이, 새"]',1,'풍백은 바람, 우사는 비, 운사는 구름을 다스렸어요.','2026-09-27T01:10:33.910Z');
