INSERT INTO "questions" VALUES(1083,3,'역사','dark','단군 이야기에서 환웅이 내려온 곳은?','["강가 모래밭","한라산 꼭대기","태백산 신단수 아래","동굴 속","바닷속 궁전"]',2,'환웅은 태백산 꼭대기 신단수 아래로 내려왔어요.','2026-09-27T01:10:33.910Z');
