INSERT INTO "questions" VALUES(1086,3,'역사','dark','사람이 되고 싶다며 환웅을 찾아온 두 동물은?','["곰과 토끼","호랑이와 늑대","곰과 호랑이","여우와 곰","사슴과 토끼"]',2,'곰과 호랑이가 사람이 되고 싶어 했어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1087,3,'역사','dark','환웅이 곰과 호랑이에게 먹으라고 준 것은?','["밥과 김치","사과와 배","쑥과 마늘","고기와 생선","떡과 과자"]',2,'쑥 한 줌과 마늘 스무 개를 주었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1088,3,'역사','dark','환웅은 곰과 호랑이에게 며칠 동안 햇빛을 보지 말라고 했나요?','["10일","100일","3일","1000일","365일"]',1,'100일 동안 햇빛을 보지 말라고 했어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1089,3,'역사','dark','곰은 며칠 만에 여자가 되었을까요?','["50일","7일","100일","21일","3일"]',3,'곰은 21일(삼칠일) 만에 여자가 되었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1090,3,'역사','dark','단군 이야기에서 호랑이는 어떻게 되었나요?','["참지 못하고 뛰쳐나가 사람이 되지 못했어요","임금이 되었어요","곰과 결혼했어요","사람이 되었어요","하늘로 올라갔어요"]',0,'호랑이는 참지 못해 사람이 되지 못했어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1091,3,'역사','dark','곰이 참고 견뎌서 된 여자를 무엇이라고 부를까요?','["유화","콩쥐","심청","선덕","웅녀"]',4,'곰(웅)이 여자(녀)가 되어 웅녀라고 해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1092,3,'역사','dark','환웅과 웅녀 사이에서 태어난 아들은?','["주몽","온조","풍백","단군왕검","환인"]',3,'환웅과 웅녀의 아들이 단군왕검이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1093,3,'역사','dark','''단군''은 어떤 일을 하는 사람을 뜻할까요?','["그림 그리는 사람","노래하는 사람","농사짓는 사람","물고기 잡는 사람","하늘에 제사를 지내는 사람"]',4,'단군은 제사를 맡은 사람(제사장)이라는 뜻이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1094,3,'역사','dark','''왕검''은 어떤 일을 하는 사람을 뜻할까요?','["아이들을 가르치는 사람","물건을 파는 상인","옷을 짓는 사람","배를 만드는 사람","나라를 다스리는 임금"]',4,'왕검은 나라를 다스리는 지도자라는 뜻이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1095,3,'역사','dark','고조선이 세워졌다고 전해지는 해는?','["2000년","기원전 100년","기원후 2333년","기원전 2333년","1945년"]',3,'고조선은 기원전 2333년에 세워졌다고 전해져요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1096,3,'역사','dark','고조선이 세워진 것을 기념하는 국경일은?','["광복절","어린이날","한글날","삼일절","개천절"]',4,'개천절은 고조선이 세워진 것을 기념하는 날이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1097,3,'역사','dark','개천절은 몇 월 며칠일까요?','["8월 15일","6월 6일","10월 3일","3월 1일","10월 9일"]',2,'개천절은 10월 3일이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1098,3,'역사','dark','''개천절''의 ''개천''은 무슨 뜻일까요?','["하늘이 열림","강을 건넘","문을 닫음","산에 오름","바다를 건넘"]',0,'개천은 하늘이 열렸다는 뜻이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1099,3,'역사','dark','단군왕검이 도읍으로 삼았던 곳으로 전해지는 곳은?','["개경","아사달","경주","한양","웅진"]',1,'단군왕검은 아사달에 도읍을 정했다고 전해져요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1100,3,'역사','dark','고조선에 있었던 법은 몇 가지라고 전해질까요?','["10가지","3가지","1가지","100가지","8가지"]',4,'고조선에는 8조법이 있었어요. 지금은 그중 3가지가 전해져요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1101,3,'역사','dark','고조선의 법에서 남을 다치게 한 사람은 어떻게 했나요?','["임금이 되었어요","곡식으로 갚았어요","그냥 용서받았어요","상을 받았어요","노래를 불렀어요"]',1,'남을 다치게 하면 곡식으로 갚아야 했어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1102,3,'역사','dark','고조선의 법에서 남의 물건을 훔친 사람은 어떻게 되었나요?','["장군이 되었어요","그 집의 노비가 되었어요","상을 받았어요","아무 일도 없었어요","물건을 더 받았어요"]',1,'도둑질한 사람은 노비가 되었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1103,3,'역사','dark','고조선의 법으로 알 수 있는 것은?','["고조선에는 사람이 살지 않았어요","고조선에는 법이 없었어요","사람의 목숨과 물건을 소중히 여겼어요","모두 똑같이 부자였어요","도둑질을 칭찬했어요"]',2,'8조법을 보면 생명과 재산을 소중히 여겼음을 알 수 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1104,3,'역사','dark','단군 이야기가 실려 있는 옛날 책은?','["난중일기","훈민정음","직지","삼국유사","동의보감"]',3,'단군 이야기는 삼국유사에 실려 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1105,3,'역사','dark','《삼국유사》를 쓴 고려의 스님은?','["세종대왕","일연","원효","의상","혜초"]',1,'일연 스님이 삼국유사를 썼어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1106,3,'역사','dark','고조선이 무너진 까닭은?','["공룡이 쳐들어와서","중국 한나라의 공격을 받아서","화산이 폭발해서","큰 홍수가 나서","백성들이 모두 떠나서"]',1,'고조선은 한나라의 공격으로 무너졌어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1107,3,'역사','dark','고조선이 무너진 해는?','["기원전 108년","1910년","1392년","기원전 2333년","기원후 108년"]',0,'고조선은 기원전 108년에 무너졌어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1108,3,'역사','dark','바람, 비, 구름을 다스리는 신하가 나오는 단군 이야기로 알 수 있는 것은?','["바다 여행을 좋아했어요","농사를 싫어했어요","고조선 사람들은 농사를 중요하게 여겼어요","싸움만 좋아했어요","비를 싫어했어요"]',2,'바람, 비, 구름은 농사에 꼭 필요해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1109,3,'역사','dark','''고조선''이라는 이름에 ''고(옛)''를 붙인 까닭은?','["높은 산에 있어서","고구려와 같은 나라라서","가장 작은 나라라서","임금 이름이 ''고''라서","나중에 세워진 조선과 구분하려고"]',4,'이성계가 세운 조선과 구분하려고 ''옛 조선''이라고 불러요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1110,3,'역사','poison','구석기 시대의 대표 도구로, 한 손에 쥐고 여러 가지로 쓴 뗀석기는?','["가락바퀴","비파형 동검","갈돌","반달 돌칼","주먹도끼"]',4,'주먹도끼는 구석기 시대의 대표 도구예요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1111,3,'역사','poison','주먹도끼가 발견되어 유명한 경기도 연천의 구석기 유적은?','["반구대 암각화","경주 첨성대","암사동 유적","강화 고인돌","전곡리 유적"]',4,'연천 전곡리에서 주먹도끼가 발견되었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1112,3,'역사','poison','선사 시대 사람들이 짐승 가죽을 꿰매 옷을 만들 때 쓴 도구는?','["재봉틀","스테이플러","풀","쇠바늘","뼈바늘"]',4,'동물 뼈를 갈아 만든 뼈바늘을 썼어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1113,3,'역사','poison','바닥이 뾰족해서 모래에 꽂아 세워 두었던 신석기 시대 그릇은?','["백자","민무늬 토기","빗살무늬 토기","플라스틱 컵","고려청자"]',2,'빗살무늬 토기는 밑이 뾰족해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1114,3,'역사','poison','빗살무늬 토기 겉면에 새겨진 무늬는?','["하트 무늬","물방울무늬","빗살(빗금) 무늬","별 무늬","꽃무늬"]',2,'빗으로 그은 듯한 빗금 무늬가 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1115,3,'역사','poison','곡식을 갈아 가루로 만들 때 쓴 신석기 시대 도구는?','["반달 돌칼","청동 거울","주먹도끼","갈돌과 갈판","비파형 동검"]',3,'갈판 위에 곡식을 놓고 갈돌로 갈았어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1116,3,'역사','poison','실을 뽑을 때 쓴 신석기 시대 도구는?','["갈돌","반달 돌칼","청동 방울","가락바퀴","주먹도끼"]',3,'가락바퀴를 돌려 실을 뽑았어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1117,3,'역사','poison','곡식의 이삭을 딸 때 쓴 반달 모양의 도구는?','["비파형 동검","가락바퀴","주먹도끼","슴베찌르개","반달 돌칼"]',4,'반달 돌칼로 벼 이삭을 땄어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1118,3,'역사','poison','청동기 시대의 대표 토기로, 겉에 무늬가 없는 그릇은?','["유리병","고려청자","빗살무늬 토기","분청사기","민무늬 토기"]',4,'무늬가 없어서 민무늬 토기라고 해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1119,3,'역사','poison','''비파형 동검''이라는 이름은 무엇을 닮아서 붙었을까요?','["악기 비파","나뭇잎","물고기","새의 부리","초승달"]',0,'칼 모양이 악기 비파를 닮았어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1120,3,'역사','poison','고인돌은 무엇으로 쓰였을까요?','["곡식 창고","사람이 사는 집","아이들 놀이터","학교","지배자의 무덤"]',4,'고인돌은 청동기 시대 지배자의 무덤이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1121,3,'역사','poison','커다란 고인돌을 보면 알 수 있는 것은?','["모든 사람이 똑같았어요","많은 사람을 부릴 수 있는 힘센 지배자가 있었어요","사람이 살지 않았어요","큰 기계가 있었어요","돌이 아주 가벼웠어요"]',1,'무거운 돌을 옮기려면 많은 사람이 필요했어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1122,3,'역사','poison','세계 유산으로 등록된 고인돌 유적이 있는 곳은?','["강화","서울","대구","제주","부산"]',0,'고창, 화순, 강화의 고인돌이 세계 유산이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1123,3,'역사','poison','세계에서 고인돌이 가장 많은 나라 가운데 하나는?','["호주","미국","캐나다","브라질","대한민국"]',4,'세계 고인돌의 절반 가까이가 우리나라에 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1124,3,'역사','poison','청동 거울은 주로 무엇에 쓰였을까요?','["옷을 꿰맬 때","농사를 지을 때","하늘에 제사를 지낼 때","아이들이 놀 때","음식을 담을 때"]',2,'청동 거울은 제사 때 쓰던 물건이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1125,3,'역사','poison','청동 방울은 어떻게 쓰였을까요?','["곡식을 갈았어요","물을 떴어요","실을 뽑았어요","고기를 잘랐어요","제사 때 흔들어 소리를 냈어요"]',4,'제사를 지낼 때 흔들어 소리를 냈어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1126,3,'역사','poison','신석기 사람들이 먹고 버린 조개껍데기가 쌓인 곳을 무엇이라고 할까요?','["조개더미","갯벌","동굴","움집","고인돌"]',0,'조개껍데기가 쌓인 곳을 조개더미라고 해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1127,3,'역사','poison','서울 암사동 유적은 어느 시대 사람들의 마을일까요?','["신석기 시대","고려 시대","조선 시대","청동기 시대","구석기 시대"]',0,'암사동에는 신석기 시대 움집 마을이 있었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1128,3,'역사','poison','울산 반구대 암각화에 새겨진 동물로 유명한 것은?','["판다","고래","공룡","낙타","펭귄"]',1,'반구대 암각화에는 고래가 많이 새겨져 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1129,3,'역사','poison','''암각화''는 어디에 새긴 그림일까요?','["나무판","유리","천","바위","종이"]',3,'암각화는 바위에 새긴 그림이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1130,3,'역사','poison','구석기 사람들이 나무 창 끝에 매달아 사냥한 뾰족한 석기는?','["민무늬 토기","갈판","가락바퀴","슴베찌르개","반달 돌칼"]',3,'슴베찌르개는 창 끝에 달아 썼어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1131,3,'역사','poison','뗀석기와 간석기는 어떻게 다를까요?','["둘 다 청동으로 만들었어요","뗀석기가 더 매끈해요","둘 다 흙을 구워 만들었어요","뗀석기는 돌을 깨뜨려, 간석기는 돌을 갈아서 만들었어요","간석기는 나무로 만들었어요"]',3,'깨뜨려 만든 것은 뗀석기, 갈아 만든 것은 간석기예요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1132,3,'역사','poison','다음 중 신석기 시대의 유물이 아닌 것은?','["가락바퀴","뼈로 만든 낚싯바늘","비파형 동검","갈돌과 갈판","빗살무늬 토기"]',2,'비파형 동검은 청동기 시대(고조선)의 유물이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1133,3,'역사','poison','다음 중 구석기 시대의 유물은?','["주먹도끼","민무늬 토기","비파형 동검","반달 돌칼","빗살무늬 토기"]',0,'주먹도끼가 구석기 시대 유물이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1134,3,'역사','poison','다음 중 청동기 시대의 유물은?','["슴베찌르개","가락바퀴","주먹도끼","빗살무늬 토기","반달 돌칼"]',4,'반달 돌칼은 청동기 시대에 벼를 거둘 때 썼어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1135,3,'역사','poison','선사 시대 유물을 직접 볼 수 있는 곳은?','["박물관","은행","소방서","수영장","마트"]',0,'박물관에서 옛 유물을 볼 수 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1136,3,'역사','poison','가락바퀴로 뽑은 실로 무엇을 만들었을까요?','["그릇","칼","배","옷","집"]',3,'실로 천을 짜서 옷을 만들었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1137,3,'역사','poison','토기를 만든 재료는?','["유리","흙(진흙)","플라스틱","청동","돌"]',1,'토기는 흙을 빚어 만든 그릇이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1138,3,'역사','poison','흙으로 빚은 토기를 단단하게 만들려고 한 일은?','["얼음에 얼렸어요","색종이를 붙였어요","모래에 묻어 두었어요","물에 담가 두었어요","불에 구웠어요"]',4,'흙 그릇을 불에 구워 단단하게 만들었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1139,3,'역사','poison','고조선의 문화가 퍼진 곳을 알려 주는 대표 유물·유적은?','["금관, 첨성대, 석굴암","비파형 동검, 고인돌, 미송리식 토기","청자, 백자, 옹기","거북선, 측우기, 해시계","주먹도끼, 뗀석기, 동굴"]',1,'이 유물들이 나온 곳을 보면 고조선의 영역을 짐작할 수 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1140,3,'역사','poison','청동으로 만든 물건이 많지 않았던 까닭은?','["청동이 너무 흔해서","너무 가벼워서","재료를 구하기 어렵고 만들기 힘들어서","금방 녹아 버려서","사람들이 싫어해서"]',2,'청동은 귀해서 지배자만 가질 수 있었어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1141,3,'역사','poison','유물의 이름과 쓰임을 바르게 짝지은 것은?','["갈돌 - 곡식 갈기","가락바퀴 - 고기 자르기","반달 돌칼 - 옷 꿰매기","빗살무늬 토기 - 사냥하기","주먹도끼 - 실 뽑기"]',0,'갈돌은 곡식을 가는 도구예요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1142,3,'역사','poison','빗살무늬 토기와 민무늬 토기 가운데 먼저 만들어진 것은?','["빗살무늬 토기","둘 다 조선 시대","민무늬 토기","알 수 없어요","둘이 같은 때"]',0,'빗살무늬 토기(신석기)가 민무늬 토기(청동기)보다 먼저예요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1143,3,'상식','grass','자석에 붙는 물건은?','["종이컵","나무젓가락","철로 된 클립","고무지우개","플라스틱 자"]',2,'자석은 철로 된 물건을 끌어당겨요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1144,3,'상식','grass','자석의 양쪽 끝을 부르는 이름은?','["앞과 뒤","해와 달","동쪽과 서쪽","N극과 S극","위와 아래"]',3,'자석에는 N극과 S극이 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1145,3,'상식','grass','소리는 물체가 어떻게 될 때 날까요?','["색이 바뀔 때","얼 때","젖을 때","멈출 때","떨릴 때"]',4,'물체가 떨리면 소리가 나요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1146,3,'상식','grass','그림자는 무엇이 막혀서 생길까요?','["바람","소리","물","빛","냄새"]',3,'빛이 물체에 막히면 그림자가 생겨요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1147,3,'상식','grass','물에 넣었을 때 뜨는 것은?','["나뭇잎","쇠못","유리구슬","동전","돌멩이"]',0,'가벼운 나뭇잎은 물에 떠요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1148,3,'상식','grass','얼음을 따뜻한 곳에 두면 무엇이 될까요?','["돌","물","모래","소금","설탕"]',1,'얼음이 녹으면 물이 돼요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1149,3,'상식','grass','어미 닭이 달걀을 품어 따뜻하게 하면 무엇이 태어날까요?','["병아리","애벌레","강아지","송아지","올챙이"]',0,'달걀에서 병아리가 태어나요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1150,3,'상식','grass','개구리가 자라는 차례로 알맞은 것은?','["알 → 개구리 → 올챙이","개구리 → 올챙이 → 알","올챙이 → 개구리 → 알","올챙이 → 알 → 개구리","알 → 올챙이 → 개구리"]',4,'개구리는 알, 올챙이를 거쳐 개구리가 돼요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1151,3,'상식','grass','나비가 자라는 차례로 알맞은 것은?','["애벌레 → 알 → 나비 → 번데기","번데기 → 알 → 애벌레 → 나비","알 → 나비 → 애벌레 → 번데기","알 → 번데기 → 애벌레 → 나비","알 → 애벌레 → 번데기 → 나비"]',4,'나비는 알, 애벌레, 번데기를 거쳐 나비가 돼요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1152,3,'상식','grass','곤충의 몸은 몇 부분으로 나뉠까요?','["머리와 배 두 부분","머리, 가슴, 배 세 부분","다섯 부분","네 부분","한 부분"]',1,'곤충의 몸은 머리, 가슴, 배로 나뉘어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1153,3,'상식','grass','잠자리의 날개는 몇 장일까요?','["2장","4장","8장","6장","1장"]',1,'잠자리는 날개가 4장이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1154,3,'상식','grass','식물의 잎이 하는 일로 알맞은 것은?','["꽃을 먹어요","햇빛을 받아 양분을 만들어요","땅을 걸어 다녀요","물고기를 잡아요","소리를 내요"]',1,'잎은 햇빛을 받아 식물이 먹을 양분을 만들어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1155,3,'상식','grass','민들레 씨는 어떻게 멀리 퍼질까요?','["물에 떠서","동물이 먹어서","사람이 던져서","꼬투리가 터져서","바람에 날려서"]',4,'솜털 달린 민들레 씨는 바람을 타고 날아가요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1156,3,'상식','grass','도깨비바늘 씨는 어떻게 퍼질까요?','["물에 떠서","꼬투리가 터져서","동물의 털이나 옷에 붙어서","새가 부리로 심어서","바람에 날려서"]',2,'갈고리 같은 가시로 털이나 옷에 붙어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1157,3,'상식','grass','다음 중 봄에 피는 꽃이 아닌 것은?','["개나리","민들레","진달래","코스모스","벚꽃"]',3,'코스모스는 가을에 피어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1158,3,'상식','grass','개구리는 추운 겨울을 어떻게 지낼까요?','["남쪽 나라로 날아가요","털갈이를 해요","나무 위에 둥지를 지어요","눈 위에서 뛰어놀아요","땅속에서 겨울잠을 자요"]',4,'개구리는 땅속에서 겨울잠을 자요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1159,3,'상식','grass','봄에 우리나라에 왔다가 가을에 따뜻한 남쪽으로 떠나는 새는?','["참새","비둘기","까치","제비","닭"]',3,'제비는 여름 철새예요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1160,3,'상식','grass','소리를 듣는 몸의 기관은?','["귀","혀","손","눈","코"]',0,'귀로 소리를 들어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1161,3,'상식','grass','음식을 잘게 씹는 일을 하는 것은?','["이(치아)","코","눈썹","귀","혀"]',0,'이로 음식을 잘게 씹어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1162,3,'상식','grass','더울 때 몸에서 땀이 나는 까닭은?','["키가 크려고","잠이 와서","기분이 좋아서","몸의 열을 식히려고","배가 고파서"]',3,'땀이 마르면서 몸을 시원하게 해 줘요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1163,3,'상식','grass','달은 스스로 빛을 낼까요?','["아니요, 햇빛을 받아 빛나요","불이 붙어서 빛나요","별빛을 모아서 빛나요","전기로 빛나요","네, 스스로 빛을 내요"]',0,'달은 햇빛을 받아서 빛나 보여요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1164,3,'상식','grass','비는 어디에서 내릴까요?','["구름","무지개","별","해","달"]',0,'구름 속 물방울이 커지면 비가 되어 내려요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1165,3,'상식','grass','바람이 불고 있다는 것을 알 수 있는 모습은?','["그림자가 생겨요","돌이 가만히 있어요","물이 얼어요","해가 떠요","나뭇잎이 흔들려요"]',4,'바람이 불면 나뭇잎과 깃발이 흔들려요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1166,3,'상식','grass','번개가 친 뒤에 들리는 큰 소리는?','["종소리","박수","천둥","메아리","휘파람"]',2,'번개가 치면 천둥소리가 나요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1167,3,'상식','grass','물은 어디에서 어디로 흐를까요?','["높은 곳에서 낮은 곳으로","어디로도 흐르지 않아요","낮은 곳에서 높은 곳으로","제자리에서 돌기만 해요","왼쪽에서만 오른쪽으로"]',0,'물은 높은 곳에서 낮은 곳으로 흘러요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1168,3,'상식','grass','바닷물을 햇볕에 오래 두어 물이 날아가면 남는 것은?','["설탕","모래","소금","기름","얼음"]',2,'바닷물이 마르면 소금이 남아요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1169,3,'상식','grass','젖은 빨래를 햇볕에 널면 마르는 까닭은?','["햇빛이 물을 색칠해서","옷이 작아져서","그림자가 물을 가져가서","물이 수증기가 되어 날아가서","옷에 물이 더 생겨서"]',3,'물이 수증기가 되어 공기 중으로 날아가요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1170,3,'상식','grass','아주 오래전에 살았던 생물의 흔적이 돌에 남은 것을 무엇이라고 할까요?','["조개","자석","화석","보석","거울"]',2,'공룡 뼈나 발자국이 돌에 남은 것을 화석이라고 해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1171,3,'상식','grass','고래는 무엇으로 숨을 쉴까요?','["아가미","폐(허파)","지느러미","피부","꼬리"]',1,'고래는 물 위로 올라와 폐로 숨을 쉬어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1172,3,'상식','grass','다음 중 다리가 없는 동물은?','["거미","뱀","개미","개구리","닭"]',1,'뱀은 다리 없이 몸으로 기어 다녀요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1173,3,'상식','grass','다음 중 부리가 있는 동물은?','["개","곰","토끼","고양이","오리"]',4,'새인 오리는 부리가 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1174,3,'상식','grass','새의 몸을 덮고 있는 것은?','["껍데기","가시","깃털","비늘","등딱지"]',2,'새의 몸은 깃털로 덮여 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1175,3,'상식','grass','물고기의 몸을 덮고 있는 것은?','["털","깃털","등딱지","비늘","가시"]',3,'물고기의 몸은 비늘로 덮여 있어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1176,3,'상식','grass','무당벌레가 즐겨 먹는 것은?','["꽃잎","돌멩이","사과","진딧물","흙"]',3,'무당벌레는 식물에 해로운 진딧물을 먹어요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1177,3,'상식','bug','두드려서 소리를 내는 악기는?','["피리","하모니카","리코더","바이올린","북"]',4,'북은 채로 두드려서 소리를 내요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1178,3,'상식','bug','입으로 불어서 소리를 내는 악기는?','["캐스터네츠","북","리코더","피아노","트라이앵글"]',2,'리코더는 입으로 불어서 소리를 내요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1179,3,'상식','bug','줄을 활로 켜서 소리를 내는 악기는?','["탬버린","바이올린","북","피리","실로폰"]',1,'바이올린은 활로 줄을 켜요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1180,3,'상식','bug','다음 중 우리나라 전통 악기가 아닌 것은?','["장구","대금","피아노","가야금","꽹과리"]',2,'피아노는 서양 악기예요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1181,3,'상식','bug','줄이 열두 개인 우리나라 전통 악기는?','["징","가야금","단소","장구","꽹과리"]',1,'가야금은 줄이 12개예요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1182,3,'상식','bug','사물놀이에서 쓰는 네 가지 악기는?','["가야금, 거문고, 해금, 대금","피아노, 기타, 북, 드럼","바이올린, 첼로, 플루트, 하프","리코더, 탬버린, 실로폰, 캐스터네츠","꽹과리, 징, 장구, 북"]',4,'사물놀이는 꽹과리, 징, 장구, 북으로 해요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1183,3,'상식','bug','우리나라를 대표하는 민요로, 지역마다 여러 가지가 전해지는 노래는?','["아리랑","반짝반짝 작은 별","생일 축하 노래","학교 종","곰 세 마리"]',0,'아리랑은 우리나라 대표 민요예요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1184,3,'상식','bug','여러 사람이 함께 소리를 맞추어 노래하는 것은?','["박수","독창","휘파람","합창","낭독"]',3,'여럿이 함께 부르는 노래는 합창이에요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1185,3,'상식','bug','악보에서 소리의 높낮이와 길이를 나타내는 기호는?','["느낌표","음표","물음표","화살표","숫자"]',1,'음표로 소리의 높이와 길이를 나타내요.','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1186,3,'상식','bug','빨강과 노랑 물감을 섞으면 무슨 색이 될까요?','["검정","파랑","주황","보라","초록"]',2,'빨강 + 노랑 = 주황','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1187,3,'상식','bug','파랑과 노랑 물감을 섞으면 무슨 색이 될까요?','["초록","갈색","보라","분홍","주황"]',0,'파랑 + 노랑 = 초록','2026-09-27T01:10:33.910Z');
