INSERT INTO "questions" VALUES(1189,3,'상식','bug','빨강 물감에 흰색 물감을 섞으면 무슨 색이 될까요?','["초록","노랑","분홍","검정","파랑"]',2,'빨강 + 흰색 = 분홍','2026-09-27T01:10:33.910Z');
INSERT INTO "questions" VALUES(1190,3,'상식','bug','다음 중 무지개 색이 아닌 것은?','["초록","노랑","빨강","보라","검정"]',4,'무지개는 빨주노초파남보, 검정은 없어요.','2026-09-27T01:10:33.910Z');
